import numpy as np
from scipy.spatial.transform import Rotation as R
q=np.array([-1.571,1.571,0,1.376,0,1.485,1.308]);
def fk(q):
 rot=R.identity();p=np.zeros(3)
 for i,(ax,d) in enumerate([('z',.36),('y',0),('z',.42),('y',0),('z',.4),('y',0),('z',.126)]):
  qq=q[i]*({3:-1}.get(i,1));rot=rot*R.from_euler(ax,qq);p+=rot.apply([0,0,d]);
 return p+rot.apply([0,0,.12])
p=fk(q);print('p',p)
for i in range(7):
 a=q.copy();a[i]+=.15;print(i,np.round(fk(a)-p,3))
